function assertEnum(path, value, options) {
  if (value == null) return;
  const v = String(value).trim();
  if (!options.includes(v)) throw new Error(`${path} must be one of: ${options.join(', ')}`);
}

function assertIsoDatetime(path, value) {
  if (value == null) return;
  if (typeof value !== 'string' || !value.trim()) throw new Error(`${path} must be an ISO8601 datetime string`);
  const s = value.trim();
  if (!(/[zZ]$/.test(s) || /[+-]\d{2}:\d{2}$/.test(s))) {
    throw new Error(`${path} must include timezone offset or Z (e.g. 2026-03-07T12:00:00Z)`);
  }
  const t = Date.parse(s);
  if (!Number.isFinite(t)) throw new Error(`${path} must be parseable ISO8601 datetime`);
}

function assertFiniteNumber(path, value) {
  if (value == null) return;
  if (typeof value !== 'number' || !Number.isFinite(value)) throw new Error(`${path} must be a finite number`);
}

function assertReference(path, value, datasetIdOrSlug) {
  if (value == null) return;
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new Error(`${path} must be a reference object`);
  }
  if (value.kind !== 'dataset_row') throw new Error(`${path}.kind must be 'dataset_row'`);
  if (value.datasetIdOrSlug !== datasetIdOrSlug) throw new Error(`${path}.datasetIdOrSlug must be '${datasetIdOrSlug}'`);
  if (value.key == null) throw new Error(`${path}.key is required`);
  assertFiniteNumber(`${path}.key`, value.key);
  const allowed = new Set(['kind', 'datasetIdOrSlug', 'key', 'label']);
  for (const k of Object.keys(value)) {
    if (!allowed.has(k)) throw new Error(`${path} has unknown field: ${k}`);
  }
}

function assertNoUnknownFields(obj, allowed, where) {
  for (const k of Object.keys(obj)) {
    if (!allowed.has(k)) throw new Error(`${where} has unknown field: ${k}`);
  }
}

function normalizeRow(row, idx) {
  if (!row || typeof row !== 'object' || Array.isArray(row)) throw new Error(`rows[${idx}] must be an object`);

  const allowedKeys = new Set([
    'account_id',
    'account_name',
    'website',
    'linkedin_url',
    'industry',
    'employee_range',
    'country',
    'state',
    'city',
    'icp_profile',
    'icp_fit',
    'icp_fit_notes',
    'status',
    'disqualify_reason',
    'owner',
    'source',
    'source_url',
    'created_at',
    'notes',
    'raw'
  ]);

  assertNoUnknownFields(row, allowedKeys, `rows[${idx}]`);

  // primary key is number
  if (row.account_id == null) throw new Error(`rows[${idx}].account_id is required`);
  assertFiniteNumber(`rows[${idx}].account_id`, row.account_id);

  // Dataset constraints enforced server-side on upsert.
  if (row.account_name == null || String(row.account_name).trim() === '') {
    throw new Error(`rows[${idx}].account_name is required (dataset constraint)`);
  }
  if (row.status == null || String(row.status).trim() === '') {
    throw new Error(`rows[${idx}].status is required (dataset constraint)`);
  }

  assertEnum(`rows[${idx}].status`, row.status, ['new', 'researched', 'qualified', 'disqualified']);
  assertEnum(`rows[${idx}].employee_range`, row.employee_range, ['1_10', '11_50', '51_200', '201_500', '501_1000', '1000_plus']);
  assertEnum(`rows[${idx}].icp_fit`, row.icp_fit, ['strong', 'medium', 'weak', 'unknown']);

  assertReference(`rows[${idx}].icp_profile`, row.icp_profile, 'icp-profiles');
  assertIsoDatetime(`rows[${idx}].created_at`, row.created_at);

  return row;
}

async function main(ctx) {
  const input = ctx.input || {};

  const starshipId = String(input.starshipId ?? ctx.env('STARSHIP_ID') ?? '');
  if (!starshipId) throw new Error('starshipId is required (or STARSHIP_ID must be available in env)');

  const datasetSlug = 'accounts';
  const mode = 'upsert';

  let rows = [];
  if (Array.isArray(input.rows) && input.rows.length) {
    rows = input.rows;
  } else if (input.row && typeof input.row === 'object' && !Array.isArray(input.row)) {
    rows = [input.row];
  }

  if (!Array.isArray(rows) || rows.length === 0) {
    throw new Error('Provide either row (object) or rows (non-empty array)');
  }

  rows = rows.map((r, idx) => normalizeRow(r, idx));

  return { starshipId, datasetSlug, mode, rows };
}

async function main(ctx) {
  const resp = ctx.input || {};
  const body = resp.body;
  if (body && typeof body === 'object' && body.success === true && 'data' in body) return body.data;
  return body ?? resp;
}
